using System;using System.IO;using System.Reflection;using System.Text;using System.Security.Cryptography;using System.Text.Json.Nodes;using Sdt.Core;using Sdt.Core.Battle;
class RngCheck { static void Main(){var b=new BattleSession();var r=new Rng(0);typeof(BattleSession).GetField("rng",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(b,r);var m=typeof(BattleSession).GetMethod("DrawRandomCurseKinds",BindingFlags.NonPublic|BindingFlags.Instance);var text=new StringBuilder();for(int i=0;i<10000;i++){r.Reseed(i);var kinds=(string[])m.Invoke(b,new object[]{6});var state=r.SaveState().Split("generation:")[1];text.Append(i).Append('|').Append(string.Join(",",kinds)).Append('|').Append(state).Append('\n');}var hash=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text.ToString()))).ToLowerInvariant();var expected=(string)JsonNode.Parse(File.ReadAllText("v8-sort-vectors.json"))["digest"];if(hash!=expected)throw new Exception(hash+" != "+expected);Console.WriteLine("10000 production C# outputs and RNG states match actual Node/V8 sort; SHA256 "+hash);}}
